+            .Select(s => s.Trim())
+            .Where(s => s.Length > 0)
+            .ToList();
+
+        if (sentences.Count <= maxSentences)
+            return string.Join(" ", sentences);
+
+        // Build word frequency map (excluding stop words)
+        var wordFrequency = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
+        foreach (var sentence in sentences)
+        {
+            foreach (Match match in WordExtractor().Matches(sentence))
+            {
+                var word = match.Value;
+                if (!StopWords.Contains(word))
+                    wordFrequency[word] = wordFrequency.GetValueOrDefault(word) + 1;
+            }
+        }
+
+        if (wordFrequency.Count == 0)
+            return sentences[0];
+
+        var maxFreq = wordFrequency.Values.Max();
+
+        // Score each sentence by sum of normalised word frequencies
+        var scored = sentences
+            .Select((sentence, index) =>
+            {
+                double score = WordExtractor().Matches(sentence)
+                    .Where(m => wordFrequency.ContainsKey(m.Value))
+                    .Sum(m => (double)wordFrequency[m.Value] / maxFreq);
+                return (Index: index, Sentence: sentence, Score: score);
+            })
+            .OrderByDescending(x => x.Score)
+            .Take(maxSentences)
+            .OrderBy(x => x.Index) // preserve original order
+            .Select(x => x.Sentence);
+
+        return string.Join(" ", scored);
+    }
+}
